import numpy as np
from math import sin,cos

def cross(a,b): return a[0]*b[1]-a[1]*b[0]
def rot(a): return np.array([[cos(a),-sin(a)],[sin(a),cos(a)]])
class Body:
 def __init__(self,x,y,w,h):
  self.p=np.array([x,y],float); self.v=np.zeros(2);self.a=0.;self.om=0.;self.w=w;self.h=h
  m=w*h/600.;self.mi=1/m;self.ii=12/(m*(w*w+h*h))
  self.local=np.array([[-w/2,-h/2],[w/2,-h/2],[w/2,h/2],[-w/2,h/2]])
 def verts(self):return self.local@rot(self.a).T+self.p

def clip(pts,n,o):
 if len(pts)<2:return pts
 a,b=pts;da=np.dot(n,a)-o;db=np.dot(n,b)-o;out=[]
 if da<=0:out.append(a)
 if db<=0:out.append(b)
 if da*db<0:out.append(a+(b-a)*da/(da-db))
 return out[:2]
def contact(a,b):
 va,vb=a.verts(),b.verts(); best=None
 for own,vs,other in [(0,va,vb),(1,vb,va)]:
  for i in range(4):
   edge=vs[(i+1)%4]-vs[i];n=np.array([edge[1],-edge[0]]);n/=np.linalg.norm(n)
   sep=min(other@n)-np.dot(vs[i],n)
   if sep>.005:return []
   if best is None or sep>best[0]:best=(sep,own,i,n)
 sep,own,i,n=best
 ref=va if own==0 else vb;inc=vb if own==0 else va
 normals=[]
 for j in range(4):
  e=inc[(j+1)%4]-inc[j];nn=np.array([e[1],-e[0]]);nn/=np.linalg.norm(nn);normals.append(np.dot(nn,n))
 j=np.argmin(normals);ps=[inc[j],inc[(j+1)%4]]
 r1,r2=ref[i],ref[(i+1)%4];t=(r2-r1)/np.linalg.norm(r2-r1)
 ps=clip(ps,-t,-np.dot(t,r1));ps=clip(ps,t,np.dot(t,r2))
 out=[]
 for p in ps:
  s=np.dot(n,p-r1)
  if s<=.01:out.append((a,b,p-n*s*.5,n if own==0 else -n,-s))
 return out

def run():
 bodies=[Body(0,20,15,40),Body(4,44,52,8),Body(23.7,76.5,11.4,57)]
 states=[];dt=1/480
 for step in range(20*120):
  time=step*dt
  if step%120==0:states.append([(b.p.copy(),b.a) for b in bodies])
  if time<.65:continue
  for b in bodies:
   b.v[1]-=500*dt;b.p+=b.v*dt;b.a+=b.om*dt
  cs=[]
  for b in bodies:
   for p in b.verts():
    if p[1]<.005:cs.append((b,None,p,np.array([0.,-1.]),-p[1]))
  for i in range(3):
   for j in range(i+1,3):cs+=contact(bodies[i],bodies[j])
  for it in range(12):
   for a,b,p,n,dep in cs:
    ra=p-a.p;rb=p-b.p if b else np.zeros(2)
    av=a.v+a.om*np.array([-ra[1],ra[0]]);bv=b.v+b.om*np.array([-rb[1],rb[0]]) if b else np.zeros(2)
    rv=bv-av;vn=np.dot(rv,n)
    if vn>=0:continue
    denom=a.mi+(b.mi if b else 0)+cross(ra,n)**2*a.ii+(cross(rb,n)**2*b.ii if b else 0)
    j=-(1.03 if vn<-25 else 1)*vn/denom
    impulse=n*j
    a.v-=impulse*a.mi;a.om-=cross(ra,impulse)*a.ii
    if b:b.v+=impulse*b.mi;b.om+=cross(rb,impulse)*b.ii
    t=np.array([-n[1],n[0]])
    av=a.v+a.om*np.array([-ra[1],ra[0]]);bv=b.v+b.om*np.array([-rb[1],rb[0]]) if b else np.zeros(2)
    jt=-np.dot(bv-av,t)/(a.mi+(b.mi if b else 0)+cross(ra,t)**2*a.ii+(cross(rb,t)**2*b.ii if b else 0))
    jt=np.clip(jt,-.55*j,.55*j);ip=t*jt
    a.v-=ip*a.mi;a.om-=cross(ra,ip)*a.ii
    if b:b.v+=ip*b.mi;b.om+=cross(rb,ip)*b.ii
  for a,b,p,n,dep in cs:
   amount=max(dep-.015,0)*.65/(a.mi+(b.mi if b else 0))
   a.p-=n*amount*a.mi
   if b:b.p+=n*amount*b.mi
  for b in bodies:b.v*=.9998;b.om*=.9998
 return states
if __name__=='__main__':
 from PIL import Image,ImageDraw
 ss=run();out=Image.new('RGB',(256*5,144*4),'#777')
 A=np.array([[1,-.135],[.045,-1]])
 for i,s in enumerate(ss):
  im=Image.new('RGB',(256,144),'#a1a6ad');d=ImageDraw.Draw(im);d.rectangle((0,120,255,144),fill='#897f5c')
  for b,(p,a),co in zip([Body(0,20,15,40),Body(4,44,52,8),Body(23.7,76.5,11.4,57)],s,['#bd3310','#dbd500','#008ccd']):
   vs=(b.local@rot(a).T+p)@A.T+np.array([123.5,120.34]);d.polygon([tuple(v) for v in vs],fill=co)
  d.text((2,2),str(i),fill='black');out.paste(im,((i%5)*256,(i//5)*144))
 out.save('.tmp/sim.png')
 print([(i,[(np.round(p,1).tolist(),round(a,2)) for p,a in s]) for i,s in enumerate(ss)])
